local config = {
  ui_story_32040401_1_dialog_content = "Deixe-me contá-los uma última vez. Um, dois, três... Sim, são todos!",
  ui_story_32040401_2_dialog_content = "Há todos os tipos de coisas aqui de todo o mundo. Illumina, o Deserto Rediesel... Tem até coisas de Longzhou aqui!",
  ui_story_32040401_3_dialog_content = "May Eu pergunto para que servem todas essas coisas, Senhora Joshua?",
  ui_story_32040401_4_dialog_content = "Oh, estes são apenas <color=#FFB400>presentes</color> que adquiri durante minhas viagens.",
  ui_story_32040401_5_dialog_content = "Desde que deixei Lumopolis, encontrei todo tipo de coisas novas e maravilhosas.",
  ui_story_32040401_6_dialog_content = "Durante uma recente visita a Northland, aprendi como as pessoas podem ser isoladas e reservadas nesta nação.",
  ui_story_32040401_7_dialog_content = "E assim, comecei a procurar uma maneira de compartilhar minhas experiências emocionantes com as crianças.",
  ui_story_32040401_8_dialog_content = "Então você tem reunido presentes de todo o mundo só para eles?",
  ui_story_32040401_9_dialog_content = "De fato. Rezo para que meus dons despertem sua curiosidade juvenil e lhes dêem um vislumbre da verdadeira vastidão de nosso mundo.",
  ui_story_32040401_10_dialog_content = "Nas areias implacáveis do Deserto de Rediesel, um grupo de aurorianos descobriu uma maneira de sobreviver juntos com base nas virtudes da lealdade e camaradagem.",
  ui_story_32040401_11_dialog_content = "E na Federação Illumina, uma única parede fica entre um campo de batalha devastado pela guerra e uma vida simples, mas gratificante.",
  ui_story_32040401_12_dialog_content = "Em Twin Pavilions Bay, até conheci um viajante vindo de Longzhou, uma terra situada do outro lado do oceano. Sua cultura e história diferem tanto da do Astra...",
  ui_story_32040401_13_dialog_content = "Se essas crianças puderem entender o grande tamanho do nosso mundo, talvez tenham ainda mais o que esperar nesta vida.",
  ui_story_32040401_14_dialog_content = "Tanto pensamento foi colocado em pequenos presentes... Você é incrível, Lady Joshua!",
  ui_story_32040401_15_dialog_content = "Hahaha, eu não iria tão longe. Além disso, isso pode me ajudar a compensar alguns dos <color=#FFB400>meus arrependimentos passados</color>.",
  ui_story_32040401_16_dialog_content = "Peço desculpas pela demora, senhora Joshua-Hum? Que surpresa ver você aqui também, PlayerName.",
  ui_story_32040401_17_dialog_content = "Ei, Novio! Então você é a pessoa Lady Joshua estava esperando!",
  ui_story_32040401_18_dialog_content = "De fato. Senhor. Novio gentilmente concordou em me ajudar a reunir as crianças, para que eu possa distribuir seus presentes.",
  ui_story_32040401_19_dialog_content = "Pensar nada disso.",
  ui_story_32040401_20_dialog_content = "<size=33>Faz Novio saber sobre sua situação, senhora Joshua?</size>",
  ui_story_32040401_21_dialog_content = "<size=33>Ele ainda não fez nenhuma menção a isso, embora eu tenha certeza de que já deve ter alguma ideia.</size>",
  ui_story_32040401_22_dialog_content = "As crianças estão prontas e esperando, meus amigos. Podemos sair assim que você carregar os presentes na carruagem.",
  ui_story_32040401_23_dialog_content = "Uau! Tantos presentes!",
  ui_story_32040401_24_dialog_content = "Este é um instrumento de Longzhou? Nunca vi nada assim antes...",
  ui_story_32040401_25_dialog_content = "Uma máquina de jogo da Illumina! Eu quero aquele!",
  ui_story_32040401_26_dialog_content = "Acalmem-se, crianças. Há uma abundância de presentes para todos.",
  ui_story_32040401_27_dialog_content = "Ufa... Isso foi muito mais cansativo do que eu pensei que seria. Não imaginava que haveria tantas crianças!",
  ui_story_32040401_28_dialog_content = "Seu trabalho duro é muito apreciado. Posso oferecer-lhe um refresco?",
  ui_story_32040401_29_dialog_content = "Claro! E obrigado novamente por ficar por aqui, Novio. não acho senhora Joshua e eu poderia ter lidado com todas aquelas crianças sem a sua ajuda.",
  ui_story_32040401_30_dialog_content = "Somos iguais a esse respeito, não somos? Pelo que entendi, você deveria apenas ajudar no transporte dos presentes, mas escolheu ficar e nos ajudar.",
  ui_story_32040401_31_dialog_content = "Bem, eu não poderia simplesmente ir embora sem me oferecer para ajudar; afinal ela é uma boa amiga. Aliás, foi por uma boa causa!",
  ui_story_32040401_32_dialog_content = "Ainda assim, eu não esperava que você ajudasse Lady Joshua com a promoção de culturas de fora de Northland.",
  ui_story_32040401_33_dialog_content = "Ela apenas deseja enriquecer a vida de nossas crianças, ampliando seus horizontes. Seus motivos são puros, disso não tenho dúvidas.",
  ui_story_32040401_34_dialog_content = "Não só isso... Rainha Bethlehem uma vez teve uma irmã mais velha que se casou com um ex-governador de Lumopolis e deixou Northland para ficar com ele.",
  ui_story_32040401_35_dialog_content = "Um ex-governador de Lumopolis?",
  ui_story_32040401_36_dialog_content = "Talvez... Ou talvez tenha sido o anterior? Minha lembrança é um tanto nebulosa. Na época, eu era apenas um mero espírito da montanha e dificilmente me preocupava com questões de governança.",
  ui_story_32040401_37_dialog_content = "Tudo o que me lembro é o olhar de solidão em seu rosto quando ela saiu do palácio.",
  ui_story_32040401_38_dialog_content = "Bem como... A expressão da Rainha Belém quando seus restos mortais foram enviados de volta para serem enterrados.",
  ui_story_32040401_39_dialog_content = "Naquela época, eu não podia ajudar a pobre senhora, e agora... Ah, por favor, me perdoe. Eu não deveria incomodá-lo com assuntos tão enfadonhos do passado.",
  ui_story_32040401_40_dialog_content = "(Então mesmo Novio tem sua própria parcela de arrependimentos, hein...)",
  ui_story_32040401_41_dialog_content = "Com licença? Foram vocês que nos trouxeram todos esses presentes?",
  ui_story_32040401_42_dialog_content = "Huh? Porque sim, nós fizemos! Se você quiser um, vá falar com a simpática senhora de cabelos brancos ali.",
  ui_story_32040401_43_dialog_content = "Eu não quero nenhum presente. Eu só quero te fazer uma pergunta.",
  ui_story_32040401_44_dialog_content = "Por que você se deu ao trabalho de nos trazer presentes do mundo exterior? O que tem para você?",
  ui_story_32040401_45_dialog_content = "E por que você está ajudando-os, Senhor Novio? Você não disse que Northland é o último paraíso deixado para os aurorianos...?",
  ui_story_32040401_46_dialog_content = "(Oh, que pergunta direta... o que aconteceu com essa garotinha?)",
  ui_story_32040401_47_dialog_content = "Nossa, isso de novo não... Por favor, não se ofenda, PlayerName.",
  ui_story_32040401_48_dialog_content = "Esta criança sonha em se tornar um cavaleiro para proteger toda Northland. Ela provou ser bastante talentosa para uma criança de sua idade.",
  ui_story_32040401_49_dialog_content = "No entanto, ela ainda tem espaço para crescer no que diz respeito à comunicação interpessoal. Peço desculpas se suas perguntas foram um pouco diretas demais.",
  ui_story_32040401_50_dialog_content = "Quanto a você, meu filho, tenha certeza de que PlayerName e senhora Joshua não nos guarde nenhuma má vontade.",
  ui_story_32040401_51_dialog_content = "Agora venha, peça desculpas aos nossos convidados.",
  ui_story_32040401_52_dialog_content = "... Desculpe.",
  ui_story_32040401_53_dialog_content = "Ouça com atenção, pequenino. Se você realmente deseja defender Northland como um cavaleiro a serviço da rainha, você deve aprender a tratar os outros com cortesia e consideração.",
  ui_story_32040401_54_dialog_content = "Embora sua honestidade e sinceridade sejam louváveis, ser franco demais às vezes pode criar mais problemas, tanto para você quanto para as pessoas que você ama.",
  ui_story_32040401_55_dialog_content = "Então você está dizendo que eu não deveria dizer a verdade?",
  ui_story_32040401_56_dialog_content = "Não criança, certamente não é isso que eu quis dizer... Peço que você se abstenha de torcer minhas palavras assim.",
  ui_story_32040401_57_dialog_content = "(Hahaha... acho que é isso que eles querem dizer com inocência infantil, hein?)",
  ui_story_32040401_58_dialog_content = "...",
  ui_story_32040401_59_dialog_content = "Eu não queria chatear Senhor Novio. Mas não entendo porque não consigo dizer o que realmente penso o tempo todo...",
  ui_story_32040401_60_dialog_content = "Olá, meu querido.",
  ui_story_32040401_61_dialog_content = "I-É você! O que exatamente você está fazendo?!",
  ui_story_32040401_62_dialog_content = "<size=33>Espera, não... Senhor Novio disse que devo tratar os outros com cortesia.</size>",
  ui_story_32040401_63_dialog_content = "... Obrigado por nos trazer presentes.",
  ui_story_32040401_64_dialog_content = "Você não precisa me agradecer, pequena. Afinal, você ainda não ganhou um presente.",
  ui_story_32040401_65_dialog_content = "E não é essa a verdade que você tem para falar?",
  ui_story_32040401_66_dialog_content = "Huh? C-Como você sabia?!",
  ui_story_32040401_67_dialog_content = "Heehee, está escrito no seu rostinho adorável.",
  ui_story_32040401_68_dialog_content = "Emm... B-Bem, não posso evitar! É tudo porque eu não entendo!",
  ui_story_32040401_69_dialog_content = "Senhor Novio disse que os aurorianos fora de Northland não poderiam se unir sob uma única causa, e é por isso que os eclipsitas vagam por toda a terra.",
  ui_story_32040401_70_dialog_content = "Mas aqueles adultos ainda pedem para você vir aqui e nos contar como é divertido lá fora?!",
  ui_story_32040401_71_dialog_content = "D-Isso não significa que ele está apenas deixando você nos enganar...?",
  ui_story_32040401_72_dialog_content = "Hmm, certamente é um assunto muito complicado, mas para uma criança da sua idade entender tanto... Você é uma garotinha incrível.",
  ui_story_32040401_73_dialog_content = "...Hã?",
  ui_story_32040401_74_dialog_content = "Para ter certeza, não há outro lugar em todo o Astra tão pacífico e sagrado quanto Northland.",
  ui_story_32040401_75_dialog_content = "Mas pessoas diferentes de lugares diferentes têm seus próprios modos de vida. Eu simplesmente queria que você e seus amigos entendessem isso.",
  ui_story_32040401_76_dialog_content = "Ao saber disso, você estará melhor equipado para forjar um futuro melhor para si mesmo.",
  ui_story_32040401_77_dialog_content = "E mesmo depois de aprender mais sobre o mundo, está tudo bem se você ainda ama Northland mais do que qualquer outro lugar.",
  ui_story_32040401_78_dialog_content = "Ah... hum...",
  ui_story_32040401_79_dialog_content = "V-Você não está apenas me dizendo o que eu quero ouvir, certo...?",
  ui_story_32040401_80_dialog_content = "Hahaha! Nossa, você realmente é um pequenino curioso.",
  ui_story_32040401_81_dialog_content = "Na verdade, você me lembra muito alguém que conheço...",
  ui_story_32040401_82_dialog_content = "Tenho uma última coisa que gostaria de compartilhar com você, criança. Você é livre para acreditar em minhas palavras ou não, desde que pense um pouco nelas.",
  ui_story_32040401_83_dialog_content = "Sua maneira honesta e direta de falar pode dar aos outros a impressão de que você é muito franco ou até mesmo imaturo.",
  ui_story_32040401_84_dialog_content = "Mas eu sei que não é o caso. Você é muito mais cuidadoso e atencioso do que muitos adultos e tem algo importante que deseja proteger.",
  ui_story_32040401_85_dialog_content = "Esta, por sua vez, é a razão pela qual você não baixa a guarda tão facilmente.",
  ui_story_32040401_86_dialog_content = "Sua natureza cautelosa e protetora é a raiz de sua suposta falta de educação.",
  ui_story_32040401_87_dialog_content = "Ainda assim, mesmo alguém como você precisa de um confidente, alguém com quem você possa conversar livremente sobre suas preocupações sem medo de ser enganado.",
  ui_story_32040401_88_dialog_content = "Caso contrário, essas mesmas preocupações continuarão a se acumular e, eventualmente, transformá-lo em uma pessoa míope e até hostil.",
  ui_story_32040401_89_dialog_content = "Pode levar algum tempo até você encontrar um confidente como este. Até então, tenha em mente suas deficiências e não deixe que elas levem a melhor sobre você.",
  ui_story_32040401_90_dialog_content = "...",
  ui_story_32040401_91_dialog_content = "Me desculpe... Isso foi muito complicado para você?",
  ui_story_32040401_92_dialog_content = "N-De jeito nenhum! Eu entendo!",
  ui_story_32040401_93_dialog_content = "Mesmo que algumas das palavras sejam um pouco difíceis de entender... Ainda acho que você está certo!",
  ui_story_32040401_94_dialog_content = "S-então tudo bem se... se nos tornássemos amigos? Você vai me ouvir e impedir que eu me desvie?",
  ui_story_32040401_95_dialog_content = "Eu?",
  ui_story_32040401_96_dialog_content = "Sim você! Você é a primeira pessoa a me entender tão bem!",
  ui_story_32040401_97_dialog_content = "Eu... Se não se importa, ficaria honrado.",
  ui_story_32040401_98_dialog_content = "Viva!!!",
  ui_story_32040401_99_dialog_content = "Minha ajuda... para guiar os outros?",
  ui_story_32040401_100_dialog_content = "Você não é obrigado a tomar chá com as outras nobres esposas se não quiser, Joshua.",
  ui_story_32040401_101_dialog_content = "Um novo governador será eleito em breve. Para você ganhar e estabelecer seu prestígio, devo desempenhar o papel de uma esposa nobre perfeita.",
  ui_story_32040401_102_dialog_content = "Agora não é hora de fazer o que eu desejo.",
  ui_story_32040401_103_dialog_content = "Mas Joshua, o que mudará se nos tornarmos os próximos governantes de Lumopolis atendendo aos caprichos daqueles aristocratas decrépitos?",
  ui_story_32040401_104_dialog_content = "Não passaríamos de fantoches da nobreza, nesse caso.",
  ui_story_32040401_105_dialog_content = "Bem dito, Daniel, mas os partidários de seu pai já se posicionaram contra nós.",
  ui_story_32040401_106_dialog_content = "Esses centristas não dão a mínima para política, mas se não contarmos com a ajuda deles, que chance temos de ganhar?!",
  ui_story_32040401_107_dialog_content = "Tive a impressão de que você estava fazendo o papel de uma esposa nobre perfeita. Por que você está me mostrando um lado tão hostil de si mesmo para mim de novo?",
  ui_story_32040401_108_dialog_content = "Me desculpe, eu só estava...",
  ui_story_32040401_109_dialog_content = "Eu sei que você está preocupado com a eleição.",
  ui_story_32040401_110_dialog_content = "E comparado a quando nos conhecemos, você se tornou uma pessoa muito mais amável e gentil... Alguém que sorri muito mais também.",
  ui_story_32040401_111_dialog_content = "É por isso que não quero que você volte a ser a pessoa que era: alguém que deve usar um disfarce o tempo todo para atingir um objetivo distante.",
  ui_story_32040401_112_dialog_content = "Eu... eu simplesmente não sei como proceder, principalmente quando aquelas nobres cabeçudas riem e ridicularizam o povo da Baixa Lumópolis.",
  ui_story_32040401_113_dialog_content = "Mas também não quero perder o apoio deles por causa disso.",
  ui_story_32040401_114_dialog_content = "Hahaha... entendo perfeitamente. Nenhum desses aristocratas pensa que posso trilhar meu próprio caminho.",
  ui_story_32040401_115_dialog_content = "O que estamos fazendo agora é explorar uma nova direção, para que possamos nos tornar dignos de guiar outros para um futuro melhor. Por causa disso, não temos ninguém para nos guiar pela estrada que está diante de nós.",
  ui_story_32040401_116_dialog_content = "Mas, pelo menos, teremos um ao outro.",
  ui_story_32040401_117_dialog_content = "Podemos não ter as respostas certas um para o outro todas as vezes, mas podemos compartilhar nossos fardos uns com os outros e evitar que nos desviemos.",
  ui_story_32040401_118_dialog_content = "Você tem razão. O caminho para o nosso futuro ideal não será fácil de percorrer... Mas, pelo menos, sempre terei um camarada confiável em quem confiar.",
  ui_story_32040401_119_dialog_content = "Suspiro... É nessas horas que você deveria se referir a nós como marido e mulher, ou pelo menos parceiros...",
  ui_story_32040401_120_dialog_content = "Aí está você, senhora Joshua! Eu estive procurando por você em todos os lugares!",
  ui_story_32040401_121_dialog_content = "Oh! Desculpe, PlayerName, devo ter me perdido.",
  ui_story_32040401_122_dialog_content = "Estou aliviada em ver que você está bem. Vamos voltar para Soroz, certo?",
  ui_story_32040401_123_dialog_content = "PlayerName... May te faço uma pergunta?",
  ui_story_32040401_124_dialog_content = "Huh? Claro.",
  ui_story_32040401_125_dialog_content = "você é amigo de Carleen e Veronica - quero dizer, Mia... Sim?",
  ui_story_32040401_126_dialog_content = "Você poderia me dizer como os dois estão se saindo ultimamente?",
  ui_story_32040401_127_dialog_content = "Como pais deles, você acha que Daniel e eu... Fizemos um bom trabalho em criá-los?",
  ui_story_32040401_128_option_content = "Claro! Você é uma pessoa tão gentil.",
  ui_story_32040401_129_dialog_content = "Claro que vocês dois fizeram! Senhor Schwartz é uma pessoa tão digna e inteligente, e você é uma das pessoas mais gentis e gentis que já conheci.",
  ui_story_32040401_130_dialog_content = "eu sou positivo Mia e Carleen aprendi muito com vocês dois!",
  ui_story_32040401_131_dialog_content = "I ver obrigado.",
  ui_story_32040401_132_option_content = "Não sei, mas tenho certeza que você fez o seu melhor.",
  ui_story_32040401_133_dialog_content = "eu, uh... eu não sou Mia ou Carleen, então eu realmente não tenho o direito de julgar a educação deles, sabe?",
  ui_story_32040401_134_dialog_content = "Perfeitamente verdade, sim.",
  ui_story_32040401_135_dialog_content = "Mas quando eu vejo o que você e Senhor Schwartz passaram, acho que posso ter uma ideia.",
  ui_story_32040401_136_dialog_content = "Vocês dois sempre estiveram dispostos a lutar pelo bem de sua família e de seus ideais... Algo que eles definitivamente aprenderam com você.",
  ui_story_32040401_137_dialog_content = "Obrigado, querido filho. Sua afirmação é mais significativa para mim do que qualquer bajulação vazia que eu costumava ouvir. Do fundo do meu coração, obrigado.",
  ui_story_32040401_138_dialog_content = "V-você não precisa ser tão cortês! Eu só estava dizendo o que estava pensando, só isso!",
  ui_story_32040401_139_dialog_content = "Muito bem. Vamos mudar de assunto para algo mais alegre.",
  ui_story_32040401_140_dialog_content = "Por que não falamos sobre nossas últimas aventuras no caminho de volta ao Colosso?",
  ui_story_32040401_141_dialog_content = "Afinal, não passo de um viajante solitário agora. Tudo o que tenho a oferecer são minhas experiências de todo o mundo."
